begin;
create extension if not exists pgtap with schema extensions;select extensions.no_plan();
alter table auth.users disable trigger on_auth_user_created;
insert into auth.users(id,email) values('f8100000-0000-4000-8000-000000000001','billing-source@local.invalid');
alter table auth.users enable trigger on_auth_user_created;
insert into public.companies(id,name) values('f8200000-0000-4000-8000-000000000001','Synthetic sourced terms');
insert into public.profiles(id,company_id,role) values('f8100000-0000-4000-8000-000000000001','f8200000-0000-4000-8000-000000000001','owner');
create temp table billing_source_input as select '{"job_number":"SYN-BILL-SOURCE","name":"Synthetic externally awarded job","customer_name":"Synthetic GC","agreement_reference":"SYN-AG","agreement_evidence":"reported_signed_no_executed_copy","agreement_amount":1000,"retainage_percent":5,"billing_submission_day":20,"billing_submission_channel":"Customer portal"}'::jsonb payload;grant select on billing_source_input to authenticated;
select set_config('request.jwt.claim.sub','f8100000-0000-4000-8000-000000000001',true);set local role authenticated;
select extensions.lives_ok($$select public.carez_intake_external_job('f8300000-0000-4000-8000-000000000001',(select payload from billing_source_input))$$,'source retainage and billing cutoff save with external intake');
select extensions.ok((select retainage_percent=5 and billing_submission_day=20 and billing_submission_channel='Customer portal' from public.project_external_intakes),'source terms are structured independently');
select extensions.ok((select billing_terms is null from public.customers where company_id='f8200000-0000-4000-8000-000000000001'),'day20 does not become net20 payment terms');
select extensions.is((select count(*)::integer from public.commercial_baselines),0,'source terms do not imply an accepted baseline');
select extensions.lives_ok($$select public.carez_intake_external_job('f8300000-0000-4000-8000-000000000001',(select payload from billing_source_input))$$,'exact retry retains one source record');
select extensions.throws_like($$select public.carez_intake_external_job('f8300000-0000-4000-8000-000000000001',(select payload||'{"retainage_percent":0}' from billing_source_input))$$,'%different values%','changed retry cannot replace recorded source terms');
select extensions.throws_like($$select public.carez_intake_external_job_source_core('f8300000-0000-4000-8000-000000000002',(select payload from billing_source_input))$$,'%permission denied%','legacy raw intake cannot bypass source validation');
select extensions.throws_like($$select public.carez_intake_external_job('f8300000-0000-4000-8000-000000000002',(select payload||'{"retainage_percent":"NaN"}' from billing_source_input))$$,'%finite%','nonfinite source rate is rejected before writes');
select extensions.lives_ok($$select public.carez_intake_external_job('f8300000-0000-4000-8000-000000000002',(select payload||'{"job_number":"SYN-BILL-MISSING","customer_id":null,"customer_name":"Other synthetic GC","retainage_percent":null,"billing_submission_day":null}' from billing_source_input))$$,'missing source terms may be recorded honestly');
select extensions.ok((select retainage_percent is null and billing_submission_day is null from public.project_external_intakes where request_id='f8300000-0000-4000-8000-000000000002'),'missing source terms never become zero or a default cutoff');
reset role;select * from extensions.finish();rollback;
